```c
// dataset.c
#include <stdlib.h>
#include <string.h>
#include "dataset.h"
dataset_t* dataset_create(size_t n){
  dataset_t* ds = (dataset_t*)malloc(sizeof(dataset_t));
  if(!ds) return NULL;
  ds->n = n;
  ds->values = (double*)malloc(n * sizeof(double));
  ds->labels = (const char**)malloc(n * sizeof(char*));
  if(!ds->values || !ds->labels){ free(ds->values); free(ds->labels); free(ds); return NULL; }
  for(size_t i=0;i<n;i++){
    ds->values[i] = (double)i;
    char tmp[16];
    snprintf(tmp, sizeof(tmp), "v%zu", i);
    ds->labels[i] = strdup(tmp);
  }
  return ds;
}
void dataset_free(dataset_t* ds){
  if(!ds) return;
  for(size_t i=0;i<ds->n;i++) free((void*)ds->labels[i]);
  free(ds->labels);
  free(ds->values);
  free(ds);
}
```
```go
// dataset.go (Go binding sketch)
package cgowa
/*
#include "dataset.h"
*/
import "C"
import (
  "errors"
)

type Dataset struct {
  N      int
  Values []float64
  Labels []string
}

// CreateDataset creates a dataset by calling the C API and copying data
func CreateDataset(n int) (Dataset, error) {
  if n <= 0 {
    return Dataset{}, errors.New("invalid size")
  }
  ds := C.dataset_create(C.size_t(n))
  if ds == nil {
    return Dataset{}, errors.New("C allocation failed")
  }
  // copy values
  vals := make([]float64, int(ds.n))
  valsPtr := (*[1 << 30]C.double)(unsafe.Pointer(ds.values))
  for i := 0; i < int(ds.n); i++ {
    vals[i] = float64(valsPtr[i])
  }
  // copy labels
  labels := make([]string, int(ds.n))
  for i := 0; i < int(ds.n); i++ {
    labels[i] = C.GoString(ds.labels[i])
  }
  C.dataset_free(ds)
  return Dataset{N: int(ds.n), Values: vals, Labels: labels}, nil
}
```

